    all_cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]

    # Apply ALL rules to determine what each cell contributes
    contributions = [[set() for _ in range(w)] for _ in range(h)]

    for r, c, val in all_cells:
        if val % 2 == 0:
            # Even: vertical line from (r,c) DOWN at column c
            for rr in range(r, h):
                contributions[rr][c].add(val)
        else:
            # Odd: 
            # - Vertical line from (r,c) DOWN at column c
            for rr in range(r, h):
                contributions[rr][c].add(val)
            # - Full horizontal line at row r
            for cc in range(w):
                contributions[r][cc].add(val)

    # Combine contributions: take max value at each intersection
    final = [[0]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            vals = contributions[r][c]
            if vals:
                # Take maximum value
                final[r][c] = max(vals)

    return final

